		}
		rel, rms := gap(got.Data, want.Data)
		t.Logf("%-10s %4dx%3dx%3d rel %.3g rms %.3g", s, got.C, got.H, got.W, rel, rms)
		if rel > 1e-4 {
			t.Errorf("%s: rel %.3g", s, rel)
		}
	}
}

