func TestVisionPixels(t *testing.T) {
	m := loadFL2VA(t)
	vc := visionConfig(t)
	pix, _ := keyframePixels(t, m, vc)
	want, _ := m.floats(t, "pixel_values_fl")
	got := append(append([]float32(nil), pix[0].Data...), pix[1].Data...)
	if len(got) != len(want) {
		t.Fatalf("%d values, want %d", len(got), len(want))
	}
	for i := range want {
